150	function runChain(
151	  req: Record<string, unknown>,
152	  res: MockRes,
153	  handlers: HandlerLayer[],
154	): void {
155	  let i = 0;
156	  // next is synchronous: each handler is fired as a fire-and-forget Promise,
157	  // with errors redirected to res._reject so res.promise always settles.
158	  //
159	  // Double-next() guard: a buggy middleware that calls next() more than once
160	  // would normally advance `i` twice, invoking the wrong handler.  We defend
161	  // against this by capturing the value of `i` that was current when next()
162	  // was called and only advancing from that slot.  Subsequent calls to the
163	  // same next() closure are silently ignored (the first call already fired
164	  // its handler).
165	  const next = (err?: unknown): void => {
166	    if (err) {
167	      res._reject(err instanceof Error ? err : new Error(String(err)));
168	      return;
169	    }
170	    if (i >= handlers.length) return;
171	    const slot = i++;
172	    const fn = handlers[slot]!.handle;
173	    Promise.resolve(
174	      (fn as (req: unknown, res: unknown, next: unknown) => unknown)(req, res, next),
175	    ).catch((e: unknown) => res._reject(e));
176	  };
177	  next();
178	}
